extra=r'''<div class="modal" id="elyaGroupModal"><div class="dialog elya130-group-dialog"><div class="dialog-head"><div><h3>New Group</h3><small class="install-note">Add at least 2 people.</small></div><button class="close" data-close="elyaGroupModal"><svg><use href="#i-close"/></svg></button></div><div class="field"><label>Group name</label><input class="search" id="elyaGroupName" maxlength="60" placeholder="Group name"></div><div class="elya130-group-search"><div class="search-wrap"><svg><use href="#i-search"/></svg><input class="search" id="elyaGroupFind" maxlength="24" placeholder="Find @username"></div><button class="secondary" id="elyaGroupFindBtn" type="button">Find</button></div><div id="elyaGroupSearchResult"></div><div class="elya130-selected" id="elyaGroupSelected"></div><button class="primary" id="elyaGroupCreate" type="button"><svg><use href="#i-group"/></svg>Create Group</button></div></div><div class="modal" id="elyaGroupInfoModal"><div class="dialog"><div class="dialog-head"><div><h3 id="elyaGroupInfoName">Group</h3><small class="install-note" id="elyaGroupInfoCount"></small></div><button class="close" data-close="elyaGroupInfoModal"><svg><use href="#i-close"/></svg></button></div><div class="elya130-members" id="elyaGroupMembers"></div></div></div><div class="elya130-reaction-picker" id="elyaReactionPicker" hidden><button type="button" data-reaction="heart"><svg><use href="#i-react-heart"/></svg></button><button type="button" data-reaction="like"><svg><use href="#i-react-like"/></svg></button><button type="button" data-reaction="laugh"><svg><use href="#i-react-laugh"/></svg></button><button type="button" data-reaction="fire"><svg><use href="#i-react-fire"/></svg></button><button type="button" data-reaction=""><svg><use href="#i-close"/></svg></button></div>'''
