css=r'''<style id="elya130Style">.elya120-chat-profile{grid-template-columns:42px 1fr auto auto}.elya130-group-info{white-space:nowrap}.elya130-transfer{padding:6px 12px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.elya130-recording{display:flex;align-items:center;gap:8px;padding:8px 11px;border-top:1px solid var(--line);background:rgba(255,80,80,.06);font-size:11px}.elya130-recording[hidden],.elya130-transfer[hidden]{display:none}.elya130-rec-dot{width:8px;height:8px;border-radius:50%;background:#ff5e66;box-shadow:0 0 0 5px rgba(255,94,102,.12);animation:elya130pulse .8s ease-in-out infinite alternate}@keyframes elya130pulse{to{opacity:.35;transform:scale(.85)}}.elya130-recording button{margin-left:auto;padding:6px 10px}.elya130-composer{grid-template-columns:auto 1fr auto auto!important}.elya130-icon{width:46px!important;height:46px!important;padding:0!important;display:grid!important;place-items:center}.elya130-attach-wrap{position:relative}.elya130-attach-menu{position:absolute;left:0;bottom:54px;width:150px;padding:6px;border:1px solid var(--line);border-radius:15px;background:rgba(10,15,22,.98);box-shadow:0 18px 46px rgba(0,0,0,.45);display:none;z-index:30}.elya130-attach-menu.open{display:grid}.elya130-attach-menu button{width:100%!important;height:auto!important;min-height:40px;display:flex!important;align-items:center;justify-content:flex-start!important;gap:9px;padding:8px 10px!important;border:0;background:transparent;color:var(--text);border-radius:10px}.elya130-attach-menu svg{width:18px;height:18px}.elya130-msg-sender{font-size:10px;font-weight:850;color:var(--accent);margin-bottom:4px}.elya130-media-img,.elya130-media-video{display:block;max-width:100%;width:min(320px,70vw);max-height:340px;border-radius:12px;object-fit:cover;background:#000}.elya130-media-video{object-fit:contain}.elya130-voice{display:flex;align-items:center;gap:9px;min-width:220px}.elya130-voice svg{width:20px;height:20px;color:var(--accent)}.elya130-voice audio{width:190px;max-width:55vw;height:34px}.elya130-file{display:flex;align-items:center;gap:9px;color:var(--text);text-decoration:none;padding:5px 0}.elya130-file svg{width:24px;height:24px;color:var(--accent)}.elya130-reactions{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}.elya130-reaction-chip{display:inline-flex;align-items:center;gap:4px;padding:3px 6px;border:1px solid rgba(255,255,255,.09);border-radius:999px;background:rgba(0,0,0,.18);font-size:9px;color:var(--muted)}.elya130-reaction-chip.mine{border-color:rgba(var(--accent-rgb),.35);color:var(--accent)}.elya130-reaction-chip svg{width:12px;height:12px}.elya130-reaction-picker{position:fixed;z-index:160000;left:50%;bottom:calc(88px + env(safe-area-inset-bottom));transform:translateX(-50%);display:flex;gap:5px;padding:7px;border:1px solid var(--line);border-radius:999px;background:rgba(8,12,18,.97);box-shadow:0 18px 50px rgba(0,0,0,.48)}.elya130-reaction-picker[hidden]{display:none}.elya130-reaction-picker button{width:40px;height:40px;border:0;border-radius:50%;background:transparent;color:var(--text);display:grid;place-items:center}.elya130-reaction-picker svg{width:20px;height:20px}.elya130-group-search{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:12px}.elya130-selected{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0;min-height:34px}.elya130-member-chip{display:flex;align-items:center;gap:6px;padding:6px 9px;border:1px solid var(--line);border-radius:999px;font-size:11px}.elya130-member-chip button{border:0;background:transparent;color:var(--muted);padding:0;width:18px;height:18px}.elya130-group-person{display:grid;grid-template-columns:40px 1fr auto;gap:9px;align-items:center;padding:9px 0}.elya130-members{display:grid;gap:4px;max-height:55vh;overflow:auto}.elya130-member-row{display:grid;grid-template-columns:40px 1fr auto;gap:10px;align-items:center;padding:9px;border-radius:13px;background:rgba(255,255,255,.025)}.elya130-admin{font-size:9px;font-weight:900;color:var(--accent);border:1px solid rgba(var(--accent-rgb),.25);border-radius:999px;padding:3px 6px}.elya120-msg{cursor:pointer}@media(max-width:699px){.elya130-composer{grid-template-columns:auto 1fr auto auto!important;gap:5px!important}.elya130-icon,.elya130-composer>button{width:42px!important;height:42px!important}.elya130-group-info{padding:7px 8px;font-size:10px}.elya130-voice audio{width:155px;max-width:48vw}}</style>'''
if 'id="elya130Style"' not in h:h=h.replace('</head>',css+'</head>',1)
script=r'''<script id="elya130SocialScript">(()=>{const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)],B=()=>window.AndroidMusic,call=(n,...a)=>{try{const b=B();if(!b||typeof b[n]!=='function')throw new Error('Native social method unavailable: '+n);return b[n](...a)}catch(e){window.toast?.(e.message||'Social feature unavailable')}};window.__elyaSocialVersion='1.3.0';let uid='',cur=null,map=new Map(),msgs=[],target=null,recording=false,timer=null,started=0,groupSearch=false;const selected=new Map(),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),T=t=>{if(!t)return'';return new Date(+t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})},D=ms=>{let x=Math.max(0,Math.floor((+ms||0)/1000));return Math.floor(x/60)+':'+String(x%60).padStart(2,'0')},I=r=>({heart:'i-react-heart',like:'i-react-like',laugh:'i-react-laugh',fire:'i-react-fire'}[r]||'i-react-heart');const oa=window.__elyaFirebaseAuthState;window.__elyaFirebaseAuthState=d=>{uid=d?.uid||'';try{oa?.(d)}catch{}};const oc=window.__elyaChatConversations;window.__elyaChatConversations=a=>{const x=Array.isArray(a)?a:[];map=new Map(x.map(v=>[v.chatId,v]));try{oc?.(x)}catch{};setTimeout(()=>{if(cur&&map.has(cur.chatId)){cur={...cur,...map.get(cur.chatId)};sync()}},0)};q('#elyaChatList')?.addEventListener('click',e=>{const r=e.target.closest?.('.elya120-conv'),c=r&&map.get(r.dataset.chat);if(c){cur=c;setTimeout(sync,0)}},true);const oo=window.__elyaChatOpened;window.__elyaChatOpened=c=>{if(c)cur={...(map.get(c.chatId)||{}),...c};try{oo?.(c)}catch{};setTimeout(sync,0)};function sync(){if(!cur)return;const g=cur.type==='group';q('#elyaChatBlock')?.toggleAttribute('hidden',g);q('#elyaGroupInfoBtn')?.toggleAttribute('hidden',!g);if(g&&q('#elyaChatOtherUser'))q('#elyaChatOtherUser').textContent=(cur.memberCount||cur.participants?.length||0)+' members'}q('#elyaGroupInfoBtn')?.addEventListener('click',()=>{if(!cur||cur.type!=='group')return;const info=cur.participantInfo||{},admins=new Set(cur.admins||[]),box=q('#elyaGroupMembers');q('#elyaGroupInfoName').textContent=cur.displayName||'Elya Group';q('#elyaGroupInfoCount').textContent=(cur.memberCount||Object.keys(info).length)+' members';box.innerHTML=Object.entries(info).map(([id,p])=>`<div class="elya130-member-row"><div class="elya120-avatar">${E((p?.displayName||'E')[0]?.toUpperCase()||'E')}</div><div><strong>${E(p?.displayName||'Elya Listener')}</strong><span class="install-note">${p?.username?'@'+E(p.username):''}</span></div>${admins.has(id)?'<span class="elya130-admin">Admin</span>':''}</div>`).join('')||'<div class="empty">Member details unavailable.</div>';openModal('elyaGroupInfoModal')});q('#elyaChatGroup')?.addEventListener('click',()=>{selected.clear();renderSel();q('#elyaGroupName').value='';q('#elyaGroupFind').value='';q('#elyaGroupSearchResult').innerHTML='';openModal('elyaGroupModal')});function renderSel(){const b=q('#elyaGroupSelected');if(!b)return;b.innerHTML=[...selected.values()].map(p=>`<span class="elya130-member-chip">${E(p.displayName||'Elya Listener')}<button type="button" data-rm="${E(p.uid)}"><svg><use href="#i-close"/></svg></button></span>`).join('');qa('[data-rm]').forEach(x=>x.onclick=()=>{selected.delete(x.dataset.rm);renderSel()})}q('#elyaGroupFindBtn')?.addEventListener('click',()=>{groupSearch=true;call('chatFindUsername',q('#elyaGroupFind')?.value||'')});q('#elyaGroupFind')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();q('#elyaGroupFindBtn')?.click()}});const os=window.__elyaChatSearchResult;window.__elyaChatSearchResult=p=>{if(q('#elyaGroupModal')?.classList.contains('open')&&groupSearch){groupSearch=false;const b=q('#elyaGroupSearchResult');if(!p?.uid){b.innerHTML='<div class="install-note">No user found.</div>';return}b.innerHTML=`<div class="elya130-group-person"><div class="elya120-avatar">${E((p.displayName||'E')[0]?.toUpperCase()||'E')}</div><div><strong>${E(p.displayName||'Elya Listener')}</strong><span class="install-note">@${E(p.username||'user')}</span></div><button class="secondary" id="elya130AddMember" type="button">Add</button></div>`;q('#elya130AddMember').onclick=()=>{selected.set(p.uid,p);renderSel();b.innerHTML=''};return}try{os?.(p)}catch{}};q('#elyaGroupCreate')?.addEventListener('click',()=>{if(selected.size<2){window.toast?.('Add at least 2 people.');return}call('chatCreateGroup',q('#elyaGroupName')?.value?.trim()||'',JSON.stringify([...selected.values()]))});window.__elyaChatGroupCreated=c=>{closeModal('elyaGroupModal');cur=c;try{oo?.(c)}catch{};call('chatListenConversations');setTimeout(sync,0)};q('#elyaChatAttach')?.addEventListener('click',e=>{e.stopPropagation();q('#elyaChatAttachMenu')?.classList.toggle('open')});document.addEventListener('click',e=>{if(!e.target.closest?.('.elya130-attach-wrap'))q('#elyaChatAttachMenu')?.classList.remove('open')});qa('[data-attach]').forEach(b=>b.addEventListener('click',()=>{if(!cur){window.toast?.('Open a chat first.');return}q('#elyaChatAttachMenu')?.classList.remove('open');call('chatPickMedia',cur.chatId,b.dataset.attach)}));window.__elyaChatUpload=(st,pct,n)=>{const b=q('#elyaChatTransfer');if(!b)return;b.hidden=false;b.textContent=st==='uploaded'?'Sent '+(n||'attachment'):st==='started'?'Preparing '+(n||'attachment')+'…':`Uploading ${n||'attachment'} · ${pct||0}%`;if(st==='uploaded')setTimeout(()=>b.hidden=true,1600)};const stop=()=>{if(timer){clearInterval(timer);timer=null}},draw=()=>{if(q('#elyaVoiceTime'))q('#elyaVoiceTime').textContent=D(Date.now()-started)};q('#elyaChatVoice')?.addEventListener('click',()=>{if(!cur){window.toast?.('Open a chat first.');return}if(!recording)call('chatStartVoice',cur.chatId);else call('chatStopVoice',true)});q('#elyaChatVoiceCancel')?.addEventListener('click',()=>call('chatStopVoice',false));window.__elyaChatVoice=(st,d)=>{const bar=q('#elyaVoiceBar'),btn=q('#elyaChatVoice');if(st==='recording'){recording=true;started=Date.now();bar.hidden=false;btn?.classList.add('danger-btn');stop();timer=setInterval(draw,250);draw()}else{recording=false;stop();bar.hidden=true;btn?.classList.remove('danger-btn');if(st==='uploading'&&q('#elyaChatTransfer')){q('#elyaChatTransfer').hidden=false;q('#elyaChatTransfer').textContent='Uploading voice message…'}}};const om=window.__elyaChatMessages;window.__elyaChatMessages=a=>{msgs=Array.isArray(a)?a:[];try{om?.(msgs)}catch{};requestAnimationFrame(enhance)};function enhance(){qa('#elyaChatMessages .elya120-msg').forEach((b,i)=>{const m=msgs[i];if(!m)return;b.dataset.msgId=m.id||'';const mine=m.senderId===uid,g=cur?.type==='group';let body='';if(g&&!mine&&m.senderName)body+=`<div class="elya130-msg-sender">${E(m.senderName)}</div>`;const k=m.kind||'text';if(k==='image'&&m.mediaUrl)body+=`<img class="elya130-media-img" src="${E(m.mediaUrl)}" alt="Shared photo" loading="lazy">`;else if(k==='video'&&m.mediaUrl)body+=`<video class="elya130-media-video" controls playsinline preload="metadata" src="${E(m.mediaUrl)}"></video>`;else if(k==='voice'&&m.mediaUrl)body+=`<div class="elya130-voice"><svg><use href="#i-mic"/></svg><audio controls preload="metadata" src="${E(m.mediaUrl)}"></audio><span>${E(D(m.durationMs))}</span></div>`;else if(k==='file'&&m.mediaUrl)body+=`<a class="elya130-file" href="${E(m.mediaUrl)}" target="_blank" rel="noopener"><svg><use href="#i-file"/></svg><span>${E(m.fileName||'Shared file')}</span></a>`;if(m.text)body+=`<div>${E(m.text)}</div>`;body+=`<small>${E(T(m.createdAt))}</small>`;const rx=m.reactions&&typeof m.reactions==='object'?m.reactions:{},counts={};for(const [id,key] of Object.entries(rx)){if(!key)continue;(counts[key]||(counts[key]={n:0,mine:false})).n++;if(id===uid)counts[key].mine=true}const chips=Object.entries(counts).map(([key,v])=>`<span class="elya130-reaction-chip ${v.mine?'mine':''}"><svg><use href="#${I(key)}"/></svg>${v.n}</span>`).join('');if(chips)body+=`<div class="elya130-reactions">${chips}</div>`;b.innerHTML=body})}q('#elyaChatMessages')?.addEventListener('click',e=>{if(e.target.closest?.('audio,video,a,button'))return;const b=e.target.closest?.('.elya120-msg');if(!b?.dataset.msgId||!cur)return;target={chatId:cur.chatId,messageId:b.dataset.msgId,message:msgs.find(x=>x.id===b.dataset.msgId)};q('#elyaReactionPicker').hidden=false});qa('#elyaReactionPicker [data-reaction]').forEach(b=>b.addEventListener('click',()=>{if(!target)return;const want=b.dataset.reaction||'',mine=target.message?.reactions?.[uid]||'';call('chatReact',target.chatId,target.messageId,mine===want?'':want);q('#elyaReactionPicker').hidden=true;target=null}));})();</script>'''
if 'id="elya130SocialScript"' not in h:h=h.replace('</body>',script+'</body>',1)
h=h.replace("window.__elyaSettingsVersion='1.2.2';window.__elyaChatVersion='1.2.2';","window.__elyaSettingsVersion='1.3.0';window.__elyaChatVersion='1.3.0';",1)
